class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        n = len(nums)
        ds = [sum(map(int, str(x))) for x in nums]
        order = sorted(range(n), key=lambda i: (ds[i], nums[i]))
        pos = [0] * n
        for r, i in enumerate(order):
            pos[i] = r
        seen = [False] * n
        swaps = 0
        for i in range(n):
            if seen[i]:
                continue
            c, j = 0, i
            while not seen[j]:
                seen[j] = True
                j = pos[j]
                c += 1
            swaps += c - 1
        return swaps

