class Solution {
public:
    int minSwaps(vector<int>& nums) {
        int n = nums.size();
        vector<pair<int,int>> a(n);
        for (int i = 0; i < n; i++) {
            int s = 0, x = nums[i];
            while (x) { s += x % 10; x /= 10; }
            a[i] = {s, i};
        }
        stable_sort(a.begin(), a.end(), [&](auto& p, auto& q) {
            if (p.first != q.first) return p.first < q.first;
            return nums[p.second] < nums[q.second];
        });
        vector<int> pos(n);
        for (int r = 0; r < n; r++) pos[a[r].second] = r;
        vector<bool> seen(n, false);
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            int c = 0, j = i;
            while (!seen[j]) { seen[j] = true; j = pos[j]; c++; }
            swaps += c - 1;
        }
        return swaps;
    }
};

