class Solution {
    public int minSwaps(int[] nums) {
        int n = nums.length;
        int[] ds = new int[n];
        for (int i = 0; i < n; i++) {
            int s = 0, x = nums[i];
            while (x > 0) { s += x % 10; x /= 10; }
            ds[i] = s;
        }
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> ds[a] != ds[b] ? ds[a] - ds[b] : nums[a] - nums[b]);
        int[] pos = new int[n];
        for (int r = 0; r < n; r++) pos[idx[r]] = r;
        boolean[] seen = new boolean[n];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            int c = 0, j = i;
            while (!seen[j]) { seen[j] = true; j = pos[j]; c++; }
            swaps += c - 1;
        }
        return swaps;
    }
}

