var minSwaps = function(nums) {
    const n = nums.length;
    const ds = nums.map(x => String(x).split('').reduce((s, d) => s + +d, 0));
    const order = [...Array(n).keys()].sort((a, b) => ds[a] - ds[b] || nums[a] - nums[b]);
    const pos = new Array(n);
    order.forEach((v, r) => pos[v] = r);
    const seen = new Array(n).fill(false);
    let swaps = 0;
    for (let i = 0; i < n; i++) {
        if (seen[i]) continue;
        let c = 0, j = i;
        while (!seen[j]) { seen[j] = true; j = pos[j]; c++; }
        swaps += c - 1;
    }
    return swaps;
};
